            ta: 'குறைந்த ஹெமாட்டோகிரிட் இரத்தத்தில் சிவப்பு அணுக்களின் விகிதம் குறைவாக இருப்பதைக் குறிக்கிறது, இது பொதுவாக சோகையுடன் தொடர்புடையது.',
