            mr: 'जास्त हेमेटोक्रिट म्हणजे लाल पेशींचे प्रमाण वाढणे, जे सामान्यतः तात्पुरत्या डिहायड्रेशनमुळे होते.',
            bn: 'উচ্চ হেমাটোক্রিট রক্তে লোহিত রক্তকণিকার বেশি ঘনত্ব নির্দেশ করে, যা পানিশূন্যতার কারণে হতে পারে।',
