            mr: 'वाढलेला बीयूएन मूत्रपिंड युरिया योग्यरित्या बाहेर टाकत नसल्याचे दर्शवतो. डिहायड्रेशन किंवा मूत्रपिंडातील कमी रक्तप्रवाह हे याचे कारण असू शकते.',
