            ta: 'அதிக யூரிக் அமிலம் மூட்டுகளில் படிகங்களை உருவாக்கி, மூட்டுவலியை (கடுமையான வலி) ஏற்படுத்தலாம் அல்லது சிறுநீரகக் கற்களை உருவாக்கலாம்.',
