            mr: 'Potassium (K) चे प्रमाण जास्त आहे, जे शरीरातील ताण किंवा वाढ दर्शवू शकते. कृपया डॉक्टरांचा सल्ला घ्या.',
            bn: 'Potassium (K)-এর মাত্রা বেশি, যা শারীরিক চাপ বা বৃদ্ধির লক্ষণ। আপনার চিকিৎসকের সাথে কথা বলুন।',
