export const TREND_SUMMARY_TEMPLATES: Record<SupportedLanguage, (testName: string, change: string, firstVal: number, lastVal: number, unit: string, status: string) => string> = {
    en: (testName, change, firstVal, lastVal, unit, status) => 
        `Your ${testName} level ${change} from ${firstVal} ${unit} to ${lastVal} ${unit}. It is ${status} compared to your first visit.`,
    hi: (testName, change, firstVal, lastVal, unit, status) => 
        `आपका ${testName} स्तर ${firstVal} ${unit} से ${change} होकर ${lastVal} ${unit} हो गया है। यह आपकी पहली यात्रा की तुलना में ${status} है।`,
    mr: (testName, change, firstVal, lastVal, unit, status) => 
        `तुमचे ${testName} प्रमाण ${firstVal} ${unit} वरून ${change} होऊन ${lastVal} ${unit} झाले आहे. पहिल्या तपासणीच्या तुलनेत ते ${status} आहे.`,
    bn: (testName, change, firstVal, lastVal, unit, status) => 
        `আপনার ${testName}-এর মাত্রা ${firstVal} ${unit} থেকে ${change} হয়ে ${lastVal} ${unit} হয়েছে। আপনার প্রথম রিপোর্টের তুলনায় এটি ${status}।`,
    te: (testName, change, firstVal, lastVal, unit, status) => 
        `మీ ${testName} స్థాయి ${firstVal} ${unit} నుండి ${lastVal} ${unit} కు ${change}. మీ మొదటి పరీక్షతో పోలిస్తే ఇది ${status}.`,
    ta: (testName, change, firstVal, lastVal, unit, status) => 
        `உங்களது ${testName} அளவு ${firstVal} ${unit}-லிருந்து ${lastVal} ${unit}-ஆக ${change}. உங்களது முதல் பரிசோதனையுடன் ஒப்பிடும்போது இது ${status}.`,
    gu: (testName, change, firstVal, lastVal, unit, status) => 
        `તમારું ${testName} સ્તર ${firstVal} ${unit} થી ${change} થઈને ${lastVal} ${unit} થયું છે. તમારી પ્રથમ મુલાકાતની સરખામણીમાં તે ${status} છે.`,
    es: (testName, change, firstVal, lastVal, unit, status) => 
        `Su nivel de ${testName} ${change} de ${firstVal} ${unit} a ${lastVal} ${unit}. Está ${status} en comparación con su primera visita.`,
    fr: (testName, change, firstVal, lastVal, unit, status) => 
        `Votre taux de ${testName} ${change} de ${firstVal} ${unit} à ${lastVal} ${unit}. Il est ${status} par rapport à votre première visite.`,
    zh: (testName, change, firstVal, lastVal, unit, status) => 
        `您的 ${testName} 水平从 ${firstVal} ${unit} ${change} 至 ${lastVal} ${unit}。与首次就诊相比，目前${status}。`
};

